cases.epl:
create schema event as com.espertech.esper.regressionlib.suite.view.ViewGroup$EventWithTags;

insert into stream1
select name, tags from event;

select name, tags('a\.b') from stream1.std:groupwin(name, tags('a\.b')).win:length(10)
having count(1) >= 5;

